// The page as an agent sees and drives it: `ctx.ui.snapshot()` reads the open windows as an
// accessibility tree, `ctx.ui.act()` presses, fills and selects through real DOM events, and a
// watcher warns about controls a person can use but an agent cannot tell apart (no accessible
// name). The guarantee is the engine's, not each plugin's: whatever a window shows, named or
// not, is in the snapshot with a ref, so a plugin needs no API of its own to be driven.
//
// Built to site/agent.js and imported by runtime.ts. Nothing at the top level touches the DOM:
// the pure parts (the text format, names, roles, keys, the services proxy, a service's members)
// are unit tested under Node (agent.test.ts); the element helpers are duck-typed for that.
//
// A window whose content is not DOM (a terminal's grid on a canvas) brings its own reading and
// writing: its type's `agent` (AgentAdapter). The snapshot shows its text as a document, `fill`
// on the document hands the text to `agent.input`, its actions are buttons. Still no API per
// plugin: the adapter is how the window is seen, the agent drives it through the same refs.
import type { AgentAdapter, ServiceDescription, UIAction, UIActOptions, UINode, UISnapshotOptions, UISnapshotWindow, UIWait, WindowHandle, WindowMode } from './types.ts'

/** How long a name or a text run may be before it is cut. */
const CLIP = 80

/** Roles a person operates: a leaf of the snapshot (its content is its name or value), and
 *  what the watcher wants a name on. */
const CONTROLS = new Set([
  'button', 'link', 'checkbox', 'radio', 'switch', 'textbox', 'searchbox', 'combobox', 'slider',
  'spinbutton', 'option', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'tab', 'treeitem', 'focusable',
])
/** Roles whose name is their text, when nothing names them otherwise. */
const NAMED_BY_CONTENT = new Set([
  'button', 'link', 'checkbox', 'radio', 'switch', 'option', 'menuitem', 'menuitemcheckbox',
  'menuitemradio', 'tab', 'treeitem', 'heading', 'cell', 'columnheader', 'rowheader', 'tooltip',
])
/** Roles shown with their text as the name and nothing below them. */
const TEXTUAL = new Set(['heading', 'status', 'alert', 'log', 'tooltip', 'img', 'math'])
const CHECKABLE = new Set(['checkbox', 'radio', 'switch', 'menuitemcheckbox', 'menuitemradio'])
/** Drawn content: an image when named, never a generic node. */
const MEDIA = new Set(['SVG', 'CANVAS', 'VIDEO', 'AUDIO'])
/** Elements that never show anything to walk into. */
const SKIP = new Set(['SCRIPT', 'STYLE', 'TEMPLATE', 'NOSCRIPT', 'DATALIST', 'IFRAME', 'OPTION', 'OPTGROUP', 'HEAD', 'META', 'LINK'])

/** What `controls()` matches: every element that may be a control (roleOf decides). */
export const CONTROL_SELECTOR = [
  'button', 'a[href]', 'input:not([type=hidden])', 'select', 'textarea', 'summary',
  '[contenteditable]:not([contenteditable=false])', '[tabindex]:not([tabindex^="-"])',
  ...[...CONTROLS].filter(role => role !== 'focusable').map(role => `[role=${role}]`),
].join(', ')

// ---- pure: names, roles, the text format, keys --------------------------------------------------

/** Whitespace collapsed, trimmed. */
export const normalize = (text: string): string => text.replace(/\s+/g, ' ').trim()

/** Cut to `CLIP` characters with an ellipsis. */
export const clip = (text: string, max = CLIP): string => text.length > max ? `${text.slice(0, max - 1)}…` : text

const tag = (el: Element): string => el.tagName.toUpperCase()
const attr = (el: Element, name: string): string | null => el.getAttribute(name)

/** The text of `node` as a name: its text nodes, without what the fields inside it hold (a
 *  label around a select is not named by the select's options). */
export function ownText(node: Node): string {
  let out = ''
  for (const child of Array.from(node.childNodes)) {
    if (child.nodeType === 3) out += child.textContent ?? ''
    else if (child.nodeType === 1) {
      const el = child as Element
      if (['SELECT', 'TEXTAREA', 'INPUT', 'SCRIPT', 'STYLE', 'TEMPLATE', 'DATALIST'].includes(tag(el))) continue
      if (attr(el, 'aria-hidden') === 'true') continue
      out += ` ${ownText(el)} `
    }
  }
  return normalize(out)
}

/** The element's role: its `role` attribute (the first token), else what its tag and type mean,
 *  else `generic` when it has an aria-label or a title. null for an element with no role of its
 *  own and no name (a container the snapshot looks through). */
export function roleOf(el: Element): string | null {
  const explicit = attr(el, 'role')?.trim().split(/\s+/)[0]
  const name = tag(el)
  // presentation / none take the implicit role away, but not a field's (it is still operable).
  if (explicit === 'presentation' || explicit === 'none') { if (!['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON'].includes(name)) return null }
  else if (explicit) return explicit
  switch (name) {
    case 'BUTTON': case 'SUMMARY': return 'button'
    case 'A': if (el.hasAttribute('href')) return 'link'; break
    case 'SELECT': return el.hasAttribute('multiple') || Number(attr(el, 'size') ?? 0) > 1 ? 'listbox' : 'combobox'
    case 'TEXTAREA': return 'textbox'
    case 'H1': case 'H2': case 'H3': case 'H4': case 'H5': case 'H6': return 'heading'
    case 'LI': return 'listitem'
    case 'OUTPUT': return 'status'
    case 'IMG': return 'img'
    case 'FIELDSET': return 'group'
    case 'DIALOG': return 'dialog'
    case 'PROGRESS': return 'progressbar'
    case 'INPUT': {
      const type = (attr(el, 'type') ?? '').toLowerCase()
      if (type === 'hidden') return null
      if (type === 'checkbox') return el.hasAttribute('switch') ? 'switch' : 'checkbox'
      if (type === 'radio') return 'radio'
      if (type === 'range') return 'slider'
      if (type === 'button' || type === 'submit' || type === 'reset' || type === 'image') return 'button'
      if (type === 'file' || type === 'color') return 'button'
      // A field is a textbox whatever it holds (number, date …): what an agent does is fill it.
      return 'textbox'
    }
  }
  const editable = attr(el, 'contenteditable')
  if (editable !== null && editable !== 'false') return 'textbox'
  const tabindex = attr(el, 'tabindex')
  if (tabindex !== null && Number(tabindex) >= 0) return 'focusable'
  // A <div title="Play"> is what many pages make a control of (webamp's transport): named, it is
  // a node of its own, `generic "Play"`, a leaf when it holds only words, a container otherwise.
  // Not for what was made presentational, a hidden input, or media (an image when named).
  if (explicit || name === 'INPUT' || MEDIA.has(name) || attr(el, 'aria-hidden') === 'true') return null
  if (normalize(attr(el, 'aria-label') ?? '') || normalize(attr(el, 'title') ?? '')) return 'generic'
  return null
}

/** Whether the element is a native form field (its content is its value, never its name). */
const isField = (el: Element): boolean => ['INPUT', 'SELECT', 'TEXTAREA'].includes(tag(el)) ||
  (attr(el, 'contenteditable') !== null && attr(el, 'contenteditable') !== 'false')

/**
 * The accessible name, the usual order: aria-label, aria-labelledby, its <label>s (a `for`, or
 * one around it), its text (a button's, a link's, a heading's; never a field's), an input
 * button's value, an image's alt, placeholder, title. Cut to 80 characters; '' when none.
 */
export function accessibleName(el: Element): string {
  const label = normalize(attr(el, 'aria-label') ?? '')
  if (label) return clip(label)
  const by = attr(el, 'aria-labelledby')
  if (by) {
    const doc = el.ownerDocument as Document | null
    const text = normalize(by.split(/\s+/).map(id => { const ref = doc?.getElementById(id); return ref ? ownText(ref) : '' }).join(' '))
    if (text) return clip(text)
  }
  const labels = (el as Partial<HTMLInputElement>).labels
  if (labels && labels.length) {
    const text = normalize(Array.from(labels).map(ownText).join(' '))
    if (text) return clip(text)
  }
  const role = roleOf(el)
  if (!isField(el) && (role === null || NAMED_BY_CONTENT.has(role) || TEXTUAL.has(role))) {
    const text = ownText(el)
    if (text) return clip(text)
  }
  if (tag(el) === 'INPUT' && ['button', 'submit', 'reset'].includes((attr(el, 'type') ?? '').toLowerCase())) {
    const value = normalize((el as HTMLInputElement).value ?? attr(el, 'value') ?? '')
    if (value) return clip(value)
  }
  if (tag(el) === 'IMG' || tag(el) === 'AREA') {
    const alt = normalize(attr(el, 'alt') ?? '')
    if (alt) return clip(alt)
  }
  for (const name of ['placeholder', 'title']) {
    const text = normalize(attr(el, name) ?? '')
    if (text) return clip(text)
  }
  return ''
}

/** Whether a role is one a person operates. */
export const isControl = (role: string): boolean => CONTROLS.has(role)

const quote = (text: string): string => JSON.stringify(text)

function line(node: UINode, depth: number): string {
  let out = `${'  '.repeat(depth)}${node.role}`
  const control = isControl(node.role)
  if (node.name || control) out += ` ${quote(node.name)}`
  if (node.value !== undefined) out += ` = ${quote(node.value)}`
  if (node.state?.length) out += ` [${node.state.join(', ')}]`
  if (node.ref) out += ` [${node.ref}]`
  if (node.call) out += ` → ${node.call}`
  if (control && !node.name) out += ' (unnamed)'
  // A document's text: on the lines below, each `| `, as the window shows it.
  if (node.text !== undefined) out += node.text ? ' =' : ' = ""'
  return out
}

/** A snapshot as text: a line per window, its nodes below it, one indent per level. */
export function formatSnapshot(windows: UISnapshotWindow[]): string {
  if (!windows.length) return 'no windows'
  const out: string[] = []
  const walk = (nodes: UINode[], depth: number) => {
    for (const node of nodes) {
      out.push(line(node, depth))
      if (node.text) for (const text of node.text.split('\n')) out.push(`${'  '.repeat(depth + 1)}| ${text}`.trimEnd())
      if (node.children) walk(node.children, depth + 1)
    }
  }
  for (const win of windows) {
    const marks = [win.type, win.mode, win.focused && 'focused', win.parent && `in ${win.parent}`, win.hidden && 'hidden', win.closed && 'closed'].filter(Boolean)
    out.push(`window ${win.id} ${quote(win.title)} (${marks.join(', ')})`)
    walk(win.nodes, 1)
    if (win.timedOut !== undefined) out.push(`(wait: timed out after ${win.timedOut} ms)`)
  }
  return out.join('\n')
}

/** How many lines of a document's text a snapshot shows by default. */
export const LINES = 40

/** `text` without the blank lines at its end (a terminal's empty rows below the prompt). */
export function trimLines(text: string): string {
  const lines = text.split(/\r?\n/)
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop()
  return lines.join('\n')
}

/** The last `lines` lines of `text`, each trimmed at its end, after `… (N more lines)` when cut. */
export function tail(text: string, lines = LINES): string {
  const trimmed = trimLines(text)
  if (!trimmed) return ''
  const all = trimmed.split('\n').map(row => row.trimEnd())
  const keep = Math.max(0, Math.floor(lines))
  if (all.length <= keep) return all.join('\n')
  const more = all.length - keep
  return [`… (${more} more line${more === 1 ? '' : 's'})`, ...keep ? all.slice(-keep) : []].join('\n')
}

/**
 * A window's content as an AgentAdapter shows it: `document "<title>"` with `ref`, its text's
 * last `lines` (when the adapter reads it; a failing `text` says why) and a button per action,
 * `→ <type>.<name>`, with the ref `actionRef(name)` gives. The DOM's nodes come after these
 * (the caller's).
 */
export function documentNode(ref: string, title: string, type: string, adapter: AgentAdapter, win: WindowHandle, lines: number, actionRef: (name: string) => string): UINode {
  const node: UINode = { ref, role: 'document', name: clip(normalize(title)) }
  if (adapter.text) {
    try { node.text = tail(String(adapter.text(win) ?? ''), lines) }
    catch (error) { node.text = `(agent.text failed: ${error instanceof Error ? error.message : String(error)})` }
  }
  const actions = Object.keys(adapter.actions ?? {})
  if (actions.length) node.children = actions.map(name => ({ ref: actionRef(name), role: 'button', name, call: `${type}.${name}` }))
  return node
}

/** What `waitFor` needs: a way to hear the window change (returns the stop) and its text. */
export interface WaitTarget {
  observe(changed: () => void): () => void
  text(): string
}

/** The defaults of `act`'s wait, filled in, `until` compiled (a bad pattern throws). */
export function waitOptions(wait: UIWait): { until?: RegExp, idleMs: number, timeoutMs: number } {
  const number = (value: unknown, fallback: number, what: string): number => {
    if (value === undefined) return fallback
    if (typeof value !== 'number' || !(value >= 0)) throw new Error(`wait.${what}: a number of milliseconds, not ${JSON.stringify(value)}`)
    return value
  }
  let until: RegExp | undefined
  if (wait.until !== undefined && wait.until !== '') {
    try { until = new RegExp(wait.until, 'm') } catch (error) { throw new Error(`wait.until: ${error instanceof Error ? error.message : String(error)}`, { cause: error }) }
  }
  return { ...until ? { until } : {}, idleMs: number(wait.idleMs, 300, 'idleMs'), timeoutMs: number(wait.timeoutMs, 10_000, 'timeoutMs') }
}

/** Whether `until` matches a window's text as the snapshot shows it: each line trimmed at its
 *  end, the blank lines at the end left out (a `$ ` prompt is `$`). */
export function matchesText(until: RegExp, text: string): boolean {
  until.lastIndex = 0
  return until.test(trimLines(text).split('\n').map(row => row.trimEnd()).join('\n'))
}

/** How often `waitFor` reads the text besides the change notices: a canvas changes no DOM. */
const POLL = 100

/**
 * Waits for a window: resolves true once `until` matches its text (checked now and after every
 * change; then idleness does not count), or, without `until`, once `idleMs` pass with no change;
 * false when `timeoutMs` pass first. A change is what `observe` reports, or the text read every
 * 100 ms being another.
 */
export function waitFor(target: WaitTarget, { until, idleMs, timeoutMs }: { until?: RegExp, idleMs: number, timeoutMs: number }): Promise<boolean> {
  return new Promise(resolve => {
    let idle: ReturnType<typeof setTimeout> | undefined
    let stop = () => {}
    const read = (): string => { try { return target.text() } catch { return '' } }
    let last = read()
    const poll = setInterval(() => {
      const now = read()
      if (now !== last) changed()
    }, POLL)
    const done = (ok: boolean) => {
      clearTimeout(idle)
      clearTimeout(deadline)
      clearInterval(poll)
      stop()
      resolve(ok)
    }
    const matches = (): boolean => until ? matchesText(until, last) : false
    function changed() {
      last = read()
      if (matches()) return done(true)
      if (until) return
      clearTimeout(idle)
      idle = setTimeout(() => done(true), idleMs)
    }
    const deadline = setTimeout(() => done(false), timeoutMs)
    stop = target.observe(changed)
    changed()
  })
}

/** A key as `press` takes it: `'Enter'`, `'a'`, `'Meta+k'`, `'Shift+Tab'`, `'Control++'`. */
export interface Key {
  key: string
  code: string
  metaKey: boolean
  ctrlKey: boolean
  altKey: boolean
  shiftKey: boolean
}

const MODIFIERS: Record<string, 'metaKey' | 'ctrlKey' | 'altKey' | 'shiftKey'> = {
  meta: 'metaKey', cmd: 'metaKey', command: 'metaKey',
  control: 'ctrlKey', ctrl: 'ctrlKey',
  alt: 'altKey', option: 'altKey',
  shift: 'shiftKey',
}
const CODES: Record<string, string> = { ' ': 'Space', '-': 'Minus', '=': 'Equal', ',': 'Comma', '.': 'Period', '/': 'Slash', ';': 'Semicolon', "'": 'Quote', '[': 'BracketLeft', ']': 'BracketRight', '\\': 'Backslash', '`': 'Backquote' }

/** Parses a key: modifiers joined with `+`, then the key (a character or a key name). */
export function parseKey(spec: string): Key {
  if (typeof spec !== 'string' || !spec) throw new Error('press: which key? (Enter, Escape, a, Meta+k …)')
  // A trailing '+' is the key itself ('Control++').
  const parts = spec.endsWith('++') ? [...spec.slice(0, -2).split('+'), '+'] : spec === '+' ? ['+'] : spec.split('+')
  let key = parts.pop() ?? ''
  const out: Key = { key: '', code: '', metaKey: false, ctrlKey: false, altKey: false, shiftKey: false }
  for (const part of parts) {
    const flag = MODIFIERS[part.toLowerCase()]
    if (!flag) throw new Error(`press: unknown modifier "${part}" in "${spec}" (Meta, Control, Alt, Shift)`)
    out[flag] = true
  }
  if (!key) throw new Error(`press: no key in "${spec}"`)
  if (key === 'Space') key = ' '
  if (key.length === 1) {
    const letter = /[a-z]/i.test(key)
    if (letter && out.shiftKey) key = key.toUpperCase()
    out.code = letter ? `Key${key.toUpperCase()}` : /\d/.test(key) ? `Digit${key}` : CODES[key] ?? ''
  } else {
    // A key name, capitalized as the DOM spells them (escape → Escape, arrowup → ArrowUp).
    key = key[0].toUpperCase() + key.slice(1)
    out.code = key
  }
  out.key = key
  return out
}

/** Names a lookup must not answer (await, JSON.stringify and the console probe them). */
const PROBES = new Set(['then', 'toJSON', 'constructor', 'valueOf', 'toString', 'inspect', 'asymmetricMatch', '$$typeof'])

/** `window.tilr.services`: `get(name)` for each read; one that is not running throws. Keys are
 *  `names()`, the running services. */
export function serviceProxy(get: (name: string) => unknown, names: () => string[]): Record<string, unknown> {
  return new Proxy({}, {
    get(_, name) {
      if (typeof name !== 'string' || PROBES.has(name)) return undefined
      const service = get(name)
      if (service === undefined || service === null) throw new Error(`no service "${name}" is running`)
      return service
    },
    has: (_, name) => typeof name === 'string' && get(name) != null,
    ownKeys: () => names(),
    getOwnPropertyDescriptor: (_, name) => typeof name === 'string' && names().includes(name)
      ? { enumerable: true, configurable: true, value: get(name) }
      : undefined,
  })
}

/** Members a description leaves out: cordis' and the runtime's plumbing (`length` and
 *  `prototype`: a callable service is a function). */
const PLUMBING = new Set(['constructor', 'ctx', 'fiber', 'config', 'name', 'scope', 'length', 'prototype'])

/** The methods and fields of `service`, own and inherited, up to `base` (cordis' Service
 *  prototype) or Object's. `_`-prefixed and symbol keys are private. With a `contract` (the
 *  member names its declared interface has, `contractOf`), a member outside it is marked
 *  `internal`; without one nothing is. */
export function members(service: object, base: object | null, contract: Set<string> | null = null): Pick<ServiceDescription, 'methods' | 'fields'> {
  const methods: ServiceDescription['methods'] = []
  const fields: ServiceDescription['fields'] = []
  const seen = new Set<string>()
  const mark = (name: string): { internal?: true } => contract && !contract.has(name) ? { internal: true } : {}
  for (let o: object | null = service; o && o !== base && o !== Object.prototype && o !== Function.prototype; o = Object.getPrototypeOf(o)) {
    for (const key of Object.getOwnPropertyNames(o)) {
      if (seen.has(key) || key.startsWith('_') || PLUMBING.has(key)) continue
      seen.add(key)
      const descriptor = Object.getOwnPropertyDescriptor(o, key)
      if (!descriptor) continue
      if (!descriptor.get && typeof descriptor.value === 'function') methods.push({ name: key, arity: (descriptor.value as (...args: unknown[]) => unknown).length, ...mark(key) })
      else fields.push({ name: key, ...mark(key) })
    }
  }
  return { methods, fields }
}

/** `text` without its comments (newlines kept, strings left alone). */
function uncomment(text: string): string {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (c === '"' || c === "'" || c === '`') {
      let j = i + 1
      while (j < text.length && text[j] !== c && text[j] !== '\n') j += text[j] === '\\' ? 2 : 1
      out += text.slice(i, j + 1)
      i = j
    } else if (c === '/' && text[i + 1] === '/') {
      while (i < text.length && text[i] !== '\n') i++
      out += '\n'
    } else if (c === '/' && text[i + 1] === '*') {
      const end = text.indexOf('*/', i + 2)
      const stop = end === -1 ? text.length : end + 2
      out += text.slice(i, stop).replace(/[^\n]/g, ' ')
      i = stop - 1
    } else out += c
  }
  return out
}

/** Every `interface <name>` in `text` (uncommented): what stands between the name and its
 *  `{` (type parameters, `extends …`) and its body, brace-matched. */
function interfaces(text: string, name: string): { header: string, body: string }[] {
  const found: { header: string, body: string }[] = []
  for (const match of text.matchAll(new RegExp(`\\binterface\\s+${name}\\b`, 'g'))) {
    const from = match.index + match[0].length
    const open = text.indexOf('{', from)
    if (open === -1) continue
    let depth = 0
    let close = open
    for (; close < text.length; close++) {
      if (text[close] === '{') depth++
      else if (text[close] === '}' && --depth === 0) break
    }
    found.push({ header: text.slice(from, open), body: text.slice(open + 1, close) })
  }
  return found
}

/** The member names of an interface's body: a name at the start of a top-level line or after a
 *  `;`, followed by `?`, `(`, `:` or `<` (`readonly`, `get` and `set` skipped). */
function memberNames(body: string): string[] {
  const names: string[] = []
  const head = /^[ \t]*(?:(?:readonly|get|set)\s+)?(\w+)\s*[?(:<]/
  let depth = 0
  let start = true
  for (let i = 0; i < body.length; i++) {
    const c = body[i]
    if (start && depth === 0) {
      const match = head.exec(body.slice(i, i + 200))
      if (match) names.push(match[1])
    }
    start = false
    if (c === '{' || c === '(' || c === '[') depth++
    else if (c === '}' || c === ')' || c === ']') depth--
    else if (c === '\n' || c === ';') start = true
  }
  return names
}

/** The type names an interface's header extends (`extends Readonly<WebViewState>` gives
 *  Readonly and WebViewState), after its own type parameters. */
function bases(header: string): string[] {
  let rest = header.trimStart()
  if (rest.startsWith('<')) {
    let depth = 0
    let i = 0
    for (; i < rest.length; i++) {
      if (rest[i] === '<') depth++
      else if (rest[i] === '>' && --depth === 0) break
    }
    rest = rest.slice(i + 1)
  }
  const match = /^\s*extends\b([\s\S]*)$/.exec(rest)
  return match ? [...match[1].matchAll(/[A-Za-z_$][\w$]*/g)].map(m => m[0]) : []
}

/** The contract of `service` in a declarations file (`site/api.d.ts`, a plugin's api.d.ts):
 *  the type `interface TilrServices { <service>: <Type> }` names (the page's own or a plugin's
 *  `declare module 'tilr'` augmentation), and the member names of `interface <Type>` and of
 *  the interfaces it extends in the same file (one level). Null when the service or its
 *  interface is not declared there. */
export function contractOf(text: string, service: string): Set<string> | null {
  const source = uncomment(text)
  const key = service.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  let type: string | null = null
  for (const { body } of interfaces(source, 'TilrServices')) {
    const match = new RegExp(`(?:^|[\\s;,])${key}\\s*\\??\\s*:\\s*(\\w+)`).exec(body)
    if (match) { type = match[1]; break }
  }
  if (!type) return null
  const declared = interfaces(source, type)
  if (!declared.length) return null
  const names = new Set<string>()
  for (const { header, body } of declared) {
    for (const name of memberNames(body)) names.add(name)
    for (const base of bases(header)) {
      if (base === type) continue
      for (const extended of interfaces(source, base)) for (const name of memberNames(extended.body)) names.add(name)
    }
  }
  return names
}

// ---- the DOM: snapshot, act, the watcher --------------------------------------------------------

/** An open window as the runtime finds it: the layout's row (or a grid tile's), and the
 *  element its content is drawn in (null: not in the page). */
export interface Frame {
  id: string
  type: string
  title: string
  mode: WindowMode
  focused: boolean
  parent?: string
  host: Element | null
  /** The element the type draws into (its `mount`'s host) and the window as `mount` got it,
   *  while mounted; and the type's AgentAdapter, if it has one. */
  content?: Element | null
  handle?: WindowHandle
  agent?: AgentAdapter
}

/** Whether `el` shows an agent anything: text, a control, a named element, through shadow
 *  roots. A window whose content is a bare canvas does not. */
export function shows(el: Element): boolean {
  const named = `${CONTROL_SELECTOR}, [aria-label], [title], img[alt]`
  const roots: (Element | ShadowRoot)[] = [el]
  for (let root = roots.pop(); root; root = roots.pop()) {
    if (normalize(root.textContent ?? '') || root.querySelector(named)) return true
    if (root instanceof Element && root.shadowRoot) roots.push(root.shadowRoot)
    for (const child of Array.from(root.querySelectorAll('*'))) if (child.shadowRoot) roots.push(child.shadowRoot)
  }
  return false
}

/** Who owns an element: the window it is in and the plugin that registered the window's type. */
export interface Owner {
  window: string
  plugin: string
}

/** The innermost ancestor (or `el`) matching `selector`, through shadow roots. */
export function closest(el: Element, selector: string): Element | null {
  for (let node: Element | null = el; node; ) {
    const found = node.closest(selector)
    if (found) return found
    const root = node.getRootNode()
    node = root instanceof ShadowRoot ? root.host : null
  }
  return null
}

/** A window's element in the page: a layout window, or a tile of the plain grid. */
const WINDOW = '.window[data-window]'
const TILE = '#grid > .tile[data-type]'

/** Not drawn: hidden, aria-hidden, inert, display: none, visibility: hidden. */
function hidden(el: Element): boolean {
  if (el.hasAttribute('hidden') || attr(el, 'aria-hidden') === 'true' || el.hasAttribute('inert')) return true
  const style = getComputedStyle(el)
  return style.display === 'none' || style.visibility === 'hidden' || style.visibility === 'collapse'
}

function valueOf(el: Element, role: string): string | undefined {
  if (el instanceof HTMLInputElement) {
    if (CHECKABLE.has(role) || role === 'button') return undefined
    return el.type === 'password' ? (el.value ? '•••' : '') : clip(el.value)
  }
  if (el instanceof HTMLTextAreaElement) return clip(el.value)
  if (el instanceof HTMLSelectElement) return clip(Array.from(el.selectedOptions).map(o => normalize(o.text)).join(', '))
  if (role === 'textbox' || role === 'searchbox' || role === 'combobox') return clip(normalize(attr(el, 'aria-valuetext') ?? el.textContent ?? ''))
  if (role === 'slider' || role === 'spinbutton' || role === 'progressbar') {
    const value = attr(el, 'aria-valuetext') ?? attr(el, 'aria-valuenow')
    return value ?? undefined
  }
  return undefined
}

function statesOf(el: Element, role: string): string[] {
  const out: string[] = []
  if (CHECKABLE.has(role)) {
    const aria = attr(el, 'aria-checked')
    const checked = el instanceof HTMLInputElement ? (el.indeterminate ? 'mixed' : el.checked) : aria === 'mixed' ? 'mixed' : aria === 'true'
    out.push(checked === 'mixed' ? 'mixed' : checked ? 'checked' : 'unchecked')
  }
  if (disabled(el)) out.push('disabled')
  if (el === deepActive()) out.push('focused')
  if ((el instanceof HTMLOptionElement && el.selected) || attr(el, 'aria-selected') === 'true') out.push('selected')
  const expanded = attr(el, 'aria-expanded')
  if (expanded === 'true') out.push('expanded')
  else if (expanded === 'false') out.push('collapsed')
  if (((el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) && el.readOnly) || attr(el, 'aria-readonly') === 'true') out.push('readonly')
  if (attr(el, 'aria-pressed') === 'true') out.push('pressed')
  const current = attr(el, 'aria-current')
  if (current !== null && current !== 'false') out.push('current')
  return out
}

function disabled(el: Element): boolean {
  return el.matches(':disabled') || closest(el, '[aria-disabled=true]') !== null
}

/** The focused element, through shadow roots. */
function deepActive(): Element | null {
  let active = document.activeElement
  while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement
  return active
}

/** Two frames for the page to redraw (React commits in one), or 100ms where frames do not come
 *  (a hidden window throttles them). */
const settle = (): Promise<void> => new Promise(done => {
  const timer = setTimeout(done, 100)
  requestAnimationFrame(() => requestAnimationFrame(() => { clearTimeout(timer); done() }))
})

/** The setter of `value` the element's prototype has: React tracks the instance's own, so a
 *  value set through it is a change React sees on the next input event. */
function setValue(el: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement, value: string): void {
  const proto = el instanceof HTMLInputElement ? HTMLInputElement.prototype : el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLSelectElement.prototype
  const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set
  if (setter) setter.call(el, value)
  else el.value = value
}

const fire = (el: Element, type: string) => el.dispatchEvent(new Event(type, { bubbles: true }))

export class Agent {
  /** Element → ref, and back (weakly: a ref does not keep a removed element alive). */
  private readonly refs = new WeakMap<Element, string>()
  private readonly elements = new Map<string, WeakRef<Element>>()
  private next = 1
  /** Refs that are no element: an AgentAdapter's actions, `<window>\0<name>` → ref and back. */
  private readonly actionRefs = new Map<string, string>()
  private readonly actions = new Map<string, { window: string, name: string }>()
  /** While a snapshot is taken: the documents (a mounted window's content, its type having an
   *  adapter) and how many lines of their text to show. */
  private documents = new Map<Element, Frame>()
  private lines = LINES
  /** Elements the watcher has warned about. */
  private readonly warned = new WeakSet<Element>()
  /** The open windows, and who owns an element: the runtime's (the layout's rows, the grid). */
  private readonly frames: () => Frame[]
  private readonly owner: (el: Element) => Owner | null

  constructor(frames: () => Frame[], owner: (el: Element) => Owner | null) {
    this.frames = frames
    this.owner = owner
  }

  /** The ref of `el`, issued on first sight. */
  ref(el: Element): string {
    let ref = this.refs.get(el)
    if (!ref) {
      ref = `e${this.next++}`
      this.refs.set(el, ref)
      this.elements.set(ref, new WeakRef(el))
    }
    return ref
  }

  /** The ref of an adapter's action of the window `window`. */
  private actionRef(window: string, name: string): string {
    const key = `${window}\0${name}`
    let ref = this.actionRefs.get(key)
    if (!ref) {
      ref = `e${this.next++}`
      this.actionRefs.set(key, ref)
      this.actions.set(ref, { window, name })
    }
    return ref
  }

  /** The live element of `ref`. */
  element(ref: string): Element {
    const el = this.elements.get(ref)?.deref()
    if (!el || !el.isConnected) throw new Error(`ref ${ref} is gone: take a new snapshot`)
    return el
  }

  snapshot(options: UISnapshotOptions = {}): string | UISnapshotWindow[] {
    const frames = this.frames().filter(frame => options.window === undefined || frame.id === options.window)
    if (options.window !== undefined && !frames.length) throw new Error(`no window "${options.window}" is open`)
    const windows = frames.map(frame => this.window(frame, options.lines))
    this.prune()
    return options.format === 'json' ? windows : formatSnapshot(windows)
  }

  private window(frame: Frame, lines = LINES): UISnapshotWindow {
    const { id, type, title, mode, focused, parent, host, content, agent, handle } = frame
    const win: UISnapshotWindow = { id, type, title, mode, focused, ...(parent ? { parent } : {}), nodes: [] }
    if (!host || !host.isConnected || closest(host, '[hidden], [inert]') || hiddenUp(host)) win.hidden = true
    else {
      this.lines = lines
      this.documents = new Map(content && agent && handle && (agent.text || agent.input || agent.actions) ? [[content, frame]] : [])
      try { win.nodes = this.children(host) } finally { this.documents = new Map() }
    }
    return win
  }

  /** The nodes below `el`: its children's, containers without a role looked through. */
  private children(el: Element | ShadowRoot): UINode[] {
    const out: UINode[] = []
    // A label's own words name its field; a frame's title bar is the window's title.
    const quiet = el instanceof Element && ((tag(el) === 'LABEL' && (el as HTMLLabelElement).control) || el.matches('.tile > header'))
    const kids = el instanceof Element && el.shadowRoot ? [...Array.from(el.shadowRoot.childNodes), ...Array.from(el.childNodes)] : Array.from(el.childNodes)
    for (const child of kids) {
      if (child.nodeType === 3) {
        const text = normalize(child.textContent ?? '')
        if (text && !quiet) out.push({ ref: '', role: 'text', name: clip(text) })
        continue
      }
      if (!(child instanceof Element) || SKIP.has(tag(child))) continue
      // A nested window is a window of its own in the snapshot.
      if (child.matches(WINDOW)) continue
      if (hidden(child)) continue
      out.push(...this.nodes(child))
    }
    // Neighbouring runs of text are one line.
    const merged: UINode[] = []
    for (const node of out) {
      const last = merged[merged.length - 1]
      if (node.role === 'text' && last?.role === 'text' && !last.ref) last.name = clip(`${last.name} ${node.name}`)
      else merged.push(node)
    }
    return merged
  }

  /** `el` as nodes: one with its role, or its children's when it has none. */
  private nodes(el: Element): UINode[] {
    const doc = this.documents.get(el)
    if (doc?.agent && doc.handle) {
      const node = documentNode(this.ref(el), doc.title, doc.type, doc.agent, doc.handle, this.lines, name => this.actionRef(doc.id, name))
      const children = [...node.children ?? [], ...this.children(el)]
      if (children.length) node.children = children
      return [node]
    }
    const tagName = tag(el)
    if (MEDIA.has(tagName)) {
      const name = accessibleName(el)
      return name || attr(el, 'role') ? [{ ref: this.ref(el), role: roleOf(el) ?? 'img', name }] : []
    }
    const role = roleOf(el)
    if (!role) return this.children(el)
    const node: UINode = { ref: this.ref(el), role, name: accessibleName(el) }
    const value = valueOf(el, role)
    if (value !== undefined) node.value = value
    const state = statesOf(el, role)
    if (state.length) node.state = state
    const call = attr(el, 'data-call')
    if (call) node.call = call
    // A control is a leaf (its content is its name), but for one that is only focusable: a
    // focus target around content (a terminal) shows what it holds.
    if (TEXTUAL.has(role) || (isControl(role) && role !== 'focusable')) return [node]
    const children = this.children(el)
    // A list item that is only words is one line: `listitem "counter"`.
    if (children.every(child => child.role === 'text')) {
      if (!node.name) node.name = clip(children.map(child => child.name).join(' '))
      return node.name || isControl(role) || role === 'listitem' ? [node] : []
    }
    node.children = children
    return [node]
  }

  /** Forgets refs whose element is gone. */
  private prune(): void {
    for (const [ref, weak] of this.elements) if (!weak.deref()?.isConnected) this.elements.delete(ref)
    const open = new Set(this.frames().map(frame => frame.id))
    for (const [ref, { window, name }] of this.actions) {
      if (open.has(window)) continue
      this.actions.delete(ref)
      this.actionRefs.delete(`${window}\0${name}`)
    }
  }

  /** The window `el` is in. */
  private frameOf(el: Element): Frame | undefined {
    const host = closest(el, `${WINDOW}, ${TILE}`)
    if (!host) return undefined
    const id = host.getAttribute('data-window') ?? host.getAttribute('data-type')
    return this.frames().find(frame => frame.id === id)
  }

  async act(ref: string, action: UIAction, value?: string, options: UIActOptions & { format?: 'text' | 'json' } = {}): Promise<string | UISnapshotWindow | null> {
    // A bad wait is refused before anything is done.
    const wait = options.wait ? waitOptions(options.wait) : null
    const verb = this.actions.get(ref)
    if (verb) return this.verb(ref, verb, action, wait, options)
    const el = ref === '' ? deepActive() ?? document.body : this.element(ref)
    const frames = this.frames()
    const frame = this.frameOf(el) ?? (ref === '' ? frames.find(f => f.focused) ?? frames[0] : undefined)
    const name = ref || 'the focused element'
    const html = el as HTMLElement
    const need = (ok: boolean, what: string) => { if (!ok) throw new Error(`${name} (${roleOf(el) ?? tag(el).toLowerCase()}) cannot ${what}`) }
    const enabled = () => { if (disabled(el)) throw new Error(`${name} is disabled`) }
    // The window's own content (or its frame): what an adapter's input takes.
    const own = frame && (el === frame.content || el === frame.host) ? frame : undefined
    const unfillable = () => {
      const role = own?.agent && el === own.content ? 'document' : roleOf(el) ?? tag(el).toLowerCase()
      const label = role === 'document' ? normalize(own?.title ?? '') : accessibleName(el)
      return new Error(`${role} ${quote(label)} cannot be filled; a window with no field needs agent.input on its WindowType (see AgentAdapter)`)
    }
    switch (action) {
      case 'click':
        enabled()
        el.scrollIntoView({ block: 'nearest' })
        if (typeof html.click === 'function') html.click()
        else el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, composed: true }))
        break
      case 'dblclick':
        enabled()
        el.scrollIntoView({ block: 'nearest' })
        el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, composed: true, detail: 2 }))
        break
      case 'fill': {
        const text = value ?? ''
        if (own?.agent?.input && own.handle) {
          await own.agent.input(own.handle, text)
          break
        }
        enabled()
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
          if (!(roleOf(el) === 'textbox' || roleOf(el) === 'searchbox' || roleOf(el) === 'combobox' || roleOf(el) === 'slider')) throw unfillable()
          if (el.readOnly) throw new Error(`${name} is read-only`)
          el.focus()
          setValue(el, text)
        } else {
          const editable = attr(el, 'contenteditable')
          if (editable === null || editable === 'false') throw unfillable()
          html.focus()
          el.textContent = text
        }
        fire(el, 'input')
        fire(el, 'change')
        break
      }
      case 'select': {
        enabled()
        const wanted = value ?? ''
        if (el instanceof HTMLSelectElement) {
          const option = Array.from(el.options).find(o => o.value === wanted) ?? Array.from(el.options).find(o => normalize(o.text) === normalize(wanted))
          if (!option) throw new Error(`${name} has no option "${wanted}" (${Array.from(el.options).map(o => quote(normalize(o.text))).join(', ')})`)
          el.focus()
          setValue(el, option.value)
          fire(el, 'input')
          fire(el, 'change')
        } else {
          const options = roleOf(el) === 'option' ? [el] : Array.from(el.querySelectorAll('[role=option]'))
          need(options.length > 0, 'select (not a <select>, a listbox or an option)')
          const option = roleOf(el) === 'option' ? el : options.find(o => attr(o, 'data-value') === wanted || accessibleName(o) === normalize(wanted))
          if (!option) throw new Error(`${name} has no option "${wanted}" (${options.map(o => quote(accessibleName(o))).join(', ')})`)
          option.scrollIntoView({ block: 'nearest' });
          (option as HTMLElement).click()
        }
        break
      }
      case 'check':
      case 'uncheck': {
        const role = roleOf(el) ?? ''
        need(CHECKABLE.has(role), action)
        const checked = el instanceof HTMLInputElement ? el.checked : attr(el, 'aria-checked') === 'true'
        if (checked === (action === 'check')) break
        enabled()
        el.scrollIntoView({ block: 'nearest' })
        html.click()
        break
      }
      case 'focus':
        need(typeof html.focus === 'function', 'take the focus')
        html.focus()
        break
      case 'press': {
        const key = parseKey(value ?? '')
        const init = { ...key, bubbles: true, cancelable: true, composed: true }
        const down = el.dispatchEvent(new KeyboardEvent('keydown', init))
        if (down && key.key.length === 1 && !key.metaKey && !key.ctrlKey) el.dispatchEvent(new KeyboardEvent('keypress', init))
        el.dispatchEvent(new KeyboardEvent('keyup', init))
        // Enter in a form's field submits it, as a browser does, unless a handler took the key.
        if (down && key.key === 'Enter' && el instanceof HTMLInputElement && el.form) el.form.requestSubmit()
        break
      }
      case 'scroll':
        el.scrollIntoView({ block: 'center' })
        break
      default:
        throw new Error(`unknown action "${String(action)}": click, dblclick, fill, select, check, uncheck, focus, press, scroll`)
    }
    return this.after(frame, wait, options)
  }

  /** `act` on an adapter's action: a click calls it. */
  private async verb(ref: string, { window, name }: { window: string, name: string }, action: UIAction, wait: ReturnType<typeof waitOptions> | null, options: UIActOptions & { format?: 'text' | 'json' }): Promise<string | UISnapshotWindow | null> {
    const frame = this.frames().find(f => f.id === window)
    const run = frame?.handle && frame.agent?.actions?.[name]
    if (!frame || !run) throw new Error(`ref ${ref} is gone: take a new snapshot`)
    if (action !== 'click') throw new Error(`button ${quote(name)} (an action of ${frame.type}) can only be clicked`)
    await run(frame.handle as WindowHandle)
    return this.after(frame, wait, options)
  }

  /** After an action: the page redrawn, the wait if asked for, the window's snapshot. */
  private async after(frame: Frame | undefined, wait: ReturnType<typeof waitOptions> | null, options: UIActOptions & { format?: 'text' | 'json' }): Promise<string | UISnapshotWindow | null> {
    await settle()
    if (!frame) return options.format === 'json' ? null : 'no windows'
    let timedOut: number | undefined
    if (wait) {
      const live = this.frames().find(f => f.id === frame.id)
      if (live && !(await this.wait(live, wait))) timedOut = wait.timeoutMs
    }
    const now = this.frames().find(f => f.id === frame.id)
    const win: UISnapshotWindow = now ? this.window(now, options.lines) : { id: frame.id, type: frame.type, title: frame.title, mode: frame.mode, focused: false, closed: true, nodes: [] }
    if (timedOut !== undefined) win.timedOut = timedOut
    return options.format === 'json' ? win : formatSnapshot([win])
  }

  /** Waits for `frame`: its adapter's `wait` (given up on after `timeoutMs`; resolved with an
   *  `until`, the text is checked here too, the adapter may have resolved on its own timeout),
   *  else its DOM and text (`waitFor`). False: timed out. */
  private async wait(frame: Frame, wait: ReturnType<typeof waitOptions>): Promise<boolean> {
    const { agent, handle, host } = frame
    if (agent?.wait && handle) {
      let timer: ReturnType<typeof setTimeout> | undefined
      const late = new Promise<boolean>(resolve => { timer = setTimeout(() => resolve(false), wait.timeoutMs) })
      const done = Promise.resolve().then(() => agent.wait?.(handle, wait.until, { idleMs: wait.idleMs, timeoutMs: wait.timeoutMs })).then(() => true, () => false)
      let settled: boolean
      try { settled = await Promise.race([done, late]) } finally { clearTimeout(timer) }
      if (!settled || !wait.until) return settled
      const until = wait.until
      try { return matchesText(until, agent.text ? String(agent.text(handle) ?? '') : host?.textContent ?? '') } catch { return false }
    }
    if (!host) return true
    return waitFor({
      observe(changed) {
        const observer = new MutationObserver(changed)
        observer.observe(host, { subtree: true, childList: true, characterData: true, attributes: true })
        return () => observer.disconnect()
      },
      text: () => agent?.text && handle ? String(agent.text(handle) ?? '') : host.textContent ?? '',
    }, wait)
  }

  /**
   * Warns about controls without an accessible name as they come into windows: once per
   * element, `report` is told whose it is. Checked a moment after they arrive (a plugin may
   * name a control right after appending it). Looks only: never changes the plugin's DOM.
   * Returns the stop.
   */
  watch(report: (owner: Owner, el: Element) => void): () => void {
    const pending = new Set<Element>()
    let timer: ReturnType<typeof setTimeout> | null = null
    const check = () => {
      timer = null
      for (const root of pending) {
        if (!root.isConnected) continue
        const candidates = root.matches(CONTROL_SELECTOR) ? [root, ...Array.from(root.querySelectorAll(CONTROL_SELECTOR))] : Array.from(root.querySelectorAll(CONTROL_SELECTOR))
        for (const el of candidates) {
          if (this.warned.has(el)) continue
          const role = roleOf(el)
          if (!role || !isControl(role) || accessibleName(el)) continue
          const owner = this.owner(el)
          if (!owner) continue
          this.warned.add(el)
          report(owner, el)
        }
      }
      pending.clear()
    }
    const observer = new MutationObserver(records => {
      for (const record of records) {
        for (const node of Array.from(record.addedNodes)) {
          if (node instanceof Element && closest(node, `${WINDOW}, .tile`)) pending.add(node)
          else if (node instanceof Element && node.querySelector(`${WINDOW}, .tile`)) pending.add(node)
        }
      }
      if (pending.size && !timer) timer = setTimeout(check, 300)
    })
    observer.observe(document.body, { childList: true, subtree: true })
    return () => {
      observer.disconnect()
      if (timer) clearTimeout(timer)
    }
  }
}

/** Whether `el` or an ancestor is display: none (a container's hidden tab). */
function hiddenUp(el: Element): boolean {
  for (let node: Element | null = el; node; node = node.parentElement) {
    if (getComputedStyle(node).display === 'none') return true
  }
  return false
}

/** `<button>`, `<div role=button>`: how a warning names the element. */
export function describeElement(el: Element): string {
  const role = attr(el, 'role')
  return `<${tag(el).toLowerCase()}${role ? ` role=${role}` : ''}>`
}
